contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test takes parameters to try to withdraw/send funds and also optionally send Ether to C.
    // It checks that when this contract (which is NOT the original deployer/owner of C) calls withdraw or withdrawAll,
    // those calls revert and therefore do not change C's balance or depositsCount.
    // We treat both withdraw(uint) and withdrawAll() and sendMoney as owner-only actions that should revert for non-owner.

    function run(uint depositAmount, uint withdrawAmount, address sendTarget, uint sendAmount) public payable {
        // require we have enough balance to send deposits to C if needed
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
            // send Ether to C to increase its balance and trigger receive()
            // This will increment depositsCount in C on success.
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }

        // Record observable state before attempting owner-only actions
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Try withdrawAll via try/catch to record whether it reverts
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Try withdraw(uint)
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try sendMoney(address,uint)
        bool sendMoneyReverted;
        try c.sendMoney(sendTarget, sendAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // After attempting owner-only calls, observable state must not have decreased depositsCount,
        // and if any of the calls reverted then address(c).balance must be unchanged from before for that call group.
        // Because we cannot attribute which call changed balance if one succeeded, we assert the stronger property:
        // If any of the three owner-only calls did NOT revert, then msg.sender would have been owner — but our test contract is not owner,
        // so all three should revert. Therefore we assert they all reverted and that depositsCount did not decrease and balance did not decrease.

        assert(withdrewAllReverted && withdrewReverted && sendMoneyReverted && address(c).balance >= beforeBalance && c.depositsCount() >= beforeDeposits);
    }

    // Allow receiving Ether for funding deposits and for receiving withdraws if owner (should not happen in correct contract)
    receive() external payable {}
}

