contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry point driving the property test
    // params: callerIsOwner indicates whether this contract should act as owner (true) or a non-owner (false)
    // withdrawAmount is the amount to attempt to withdraw
    function run(bool callerIsOwner, uint withdrawAmount) public payable {
        // No precondition on params
        // Ensure this test contract has enough ETH if we will send to C for deposits
        // We'll send some ETH to C first so withdraw can potentially succeed for owner
        uint initialFund = 1 ether;
        // require enough balance to fund initial deposit
        require(address(this).balance >= initialFund, "need test contract balance");

        // Deposit funds into C by sending Ether to it (increments depositsCount)
        // The InvMutTest contract is the deployer/owner of C per the problem statement
        c.f{value: initialFund}();

        // Capture observable state before withdraw attempts
        uint beforeDeposits = c.depositsCount();
        address beforeOwner = c.owner();
        uint contractBalBefore = address(c).balance;

        // Decide whether to act as owner or attempt to act as non-owner.
        // If callerIsOwner==true, we (this contract) are owner because C was deployed with msg.sender = this contract.
        // If callerIsOwner==false, we simulate a non-owner by using a low-level call from a different address.
        bool withdrawReverted;
        if (callerIsOwner) {
            // call withdraw and withdrawAll as owner: should NOT revert
            withdrawReverted = false;
            try c.withdraw(withdrawAmount) {
            } catch {
                withdrawReverted = true;
            }

            bool withdrawAllReverted = false;
            try c.withdrawAll() {
            } catch {
                withdrawAllReverted = true;
            }

            // Owner calls must not revert (so both flags false)
            // We combine into withdrawReverted for the final assert by OR-ing
            withdrawReverted = withdrawReverted || withdrawAllReverted;
        } else {
            // Simulate non-owner by invoking via address.call from a different address.
            // We cannot change msg.sender inside this contract, but we can create a minimal proxy contract on-the-fly is forbidden by constraints.
            // Instead we use low-level call to c.withdraw from this contract but wrap expectation: such calls should revert because msg.sender != owner.
            // Since we cannot change msg.sender, this branch represents a non-owner attempt that should revert when senders differ.
            // We'll detect revert by calling via try/catch of external call to this contract which then calls c as a non-owner.

            // Create a small helper contract inline is not allowed. So instead, we assert property logically: if this contract is not the owner, withdraw must revert.
            // Here we set withdrawReverted by checking equality of owner; if owner != address(this) then calling withdraw would revert.
            // But we still perform a call attempt to observe behavior: it must revert if not owner.
            bool didRevert = false;
            try c.withdraw(withdrawAmount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
            withdrawReverted = didRevert;
        }

        // Read after-state
        uint afterDeposits = c.depositsCount();
        address afterOwner = c.owner();
        uint contractBalAfter = address(c).balance;

        // General rule asserted:
        // 1) depositsCount must not decrease
        // 2) owner must never change through withdraw/withdrawAll
        // 3) If caller was not the owner (owner != address(this)), withdraw must have reverted; if caller was owner, withdraw should not have reverted
        // 4) Contract balance after owner's successful withdraw(s) is <= before (no increase)

        assert(
            // deposits monotonic non-decreasing
            afterDeposits >= beforeDeposits
            // owner unchanged
            && afterOwner == beforeOwner
            // revert behavior consistent with ownership
            && ( (beforeOwner == address(this)) ? (withdrawReverted == false) : (withdrawReverted == true) )
            // balance didn't increase as a result of withdraws
            && contractBalAfter <= contractBalBefore
        );
    }

    // allow receiving Ether for initial funding
    receive() external payable {}
}

