            try c.sendMoney(target, value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Make a non-owner call by using a low-level call from this contract but setting msg.sender != owner is impossible here.
            // Instead, perform the call via an external contract created on the fly using assembly that forwards the call,
            // so msg.sender will be that new contract (not the owner).
            address forwarder;
            bytes memory code = hex"602a600c600039602a6000f3600052600a6016f3"; // minimal contract that forwards calldata and value
            assembly {
                forwarder := create(0, add(code, 0x20), mload(code))
            }
            // call sendMoney on c from the forwarder using its own call: construct calldata for c.sendMoney(target,value)
            bytes memory calldataFor = abi.encodeWithSignature("sendMoney(address,uint256)", target, value);
            // low-level call from this contract to forwarder to instruct it to call c
            // we encode the target contract and calldata inside the forwarded call: the simple forwarder will just forward whatever calldata it receives,
            // so we call the forwarder with calldataFor but set the destination by calling the forwarder which in turn will call c because the forwarder uses CALL to msg.origin? 
            // Simpler: have the forwarder perform a CALL to c by embedding c's address and calldata in its code is complex.
            // Instead we perform a call to c via the forwarder by using delegatecall pattern: but delegatecall keeps msg.sender. To ensure a non-owner msg.sender, we perform a call from the forwarder to c using CALL opcode by invoking the forwarder with specially crafted calldata that it will use as-is.
            // For robustness in this constrained context, just perform a call from forwarder to c using CALL via assembly here:
            bool lowOk;
            assembly {
                let ptr := mload(0x40)
                mstore(ptr, mload(add(calldataFor, 0x20)))
                // make call: forwarder -> c
                lowOk := call(gas(), forwarder, 0, add(calldataFor, 0x20), mload(calldataFor), 0, 0)
            }
            reverted = !lowOk;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if a non-owner attempted the call it must have reverted and left balance and depositsCount unchanged;
        // if the owner attempted the call, it may or may not revert (e.g., due to target), but state change is allowed.
        if (!callAsOwner) {
            assert(reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance);
        } else {
            // when owner calls, we assert nothing about revert, but require that depositsCount never decreases and that balance never increases unexpectedly
            assert(afterDeposits >= beforeDeposits && afterBalance <= beforeBalance + value);
        }
    }

    receive() external payable {}
}

