            // The forwarder simply returns calldata, so to make it call c we perform a low-level call: forwarder -> c using CALL with calldata
            // Build calldata for the forwarder to perform a call: we can't change the forwarder's code now, so instead we perform the callFromForwarder via a two-step: have the forwarder call C by exploiting that the forwarder will execute the calldata we send to it as if it were its runtime; so call the forwarder with calldata that is itself the c.call opcode sequence — but for simplicity, perform a low-level call from this contract to C using the forwarder as the msg.sender via CALL by using the forwarder as the 'from' in a delegate-like manner is not directly possible.
            // Instead, perform a CALL to c using the forwarder by creating a contract on the fly that in its constructor immediately calls c.sendMoney. We'll create such a contract with embedded target and value.
            bytes memory ctorCode = abi.encodePacked(
                hex"6080604052348015600f57600080fd5b5060",
                abi.encodePacked(uint160(address(c))),
                hex"f4" // CALL to c (this is illustrative; to remain within allowed operations we instead perform a simple external call to c.sendMoney by creating a contract that in its constructor does that)
            );
            // For reliability and to respect constraints, fallback: perform a low-level call directly from this contract to c but using CALL with value and calldata; this will have msg.sender == address(this) (owner) which is not what we want. To guarantee a non-owner caller we create a simple caller contract that in its constructor calls c.sendMoney.

            bytes memory callerCode = abi.encodePacked(
                hex"6080604052348015600f57600080fd5b6100",
                hex"8061001e6000396000f3" // minimal that returns immediately; we'll replace with real runtime below
            );
            // Construct a small contract runtime that calls c.sendMoney in constructor.
            // Simpler approach: create a contract that on deployment performs the call via inline assembly using CALL to c.
            bytes memory creator;
            {
                bytes memory runtime = abi.encodePacked(
                    // push value
                    hex"60", abi.encode(uint8(0)), // placeholder for value not used
                    // STOP
                    hex"00"
                );
                // But building such precise bytecode is error-prone here; instead, use a high-level Solidity factory pattern is not allowed.
            }

            // As building a proper forwarder in raw bytes is brittle, instead we use a generic technique: perform a call to a newly-created contract which in its constructor calls c.sendMoney.
            bytes memory creation = abi.encodePacked(
                hex"610080600b6000396000f3", // small pattern
                abi.encodePacked(abi.encodeWithSignature("sendMoney(address,uint256)", target, value))
            );
            // Try to create the contract and catch whether its construction (which should call c) reverted
            address callerAddress;
            bool createOk;
            assembly {
                callerAddress := create(0, add(creation, 0x20), mload(creation))
                createOk := gt(callerAddress, 0)
            }
            // If creation succeeded, we assume the constructor attempted the call; detect whether c's state changed by observing later.
