        assert(
            ( !callAsOwner && reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance )
            ||
            ( callAsOwner && afterDeposits >= beforeDeposits && afterBalance <= beforeBalance + value )
        );
    }

