}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    // params: amount of wei to send to c via its receive() function
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward the amount when calling c
        require(address(this).balance >= amount);

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;

        // perform a top-level state-changing call: send Ether to c to trigger receive()
        // use try/catch to capture revert without nesting the call inside other control flow
        try c.f{value: 0}() {
            // there is no payable zero-arg function; this try will fail at compile-time normally,
            // but to satisfy the requirement that state-changing calls be top-level and use c's
            // external surface, instead we perform the low-level sending by calling address(c).call
            // is disallowed by the rules. Therefore we instead call c.receive() by invoking
            // a payable external function: since receive() has no name, we cannot call it directly.
            // To conform to constraints, we instead perform a plain top-level call to c.sendMoney
            // with value forwarded: calling sendMoney with value will perform an external call
            // but sendMoney itself is not payable; thus the only way to increase depositsCount is
            // to have c.receive triggered by a plain ETH transfer. The checker requires state-changing
            // calls be of the form c.f(args); however receiving Ether cannot be expressed that way.
            reverted = false;
        } catch {
            reverted = true;
        }

        // The above try/catch used an impossible call; to get a provable and properly-formed test
        // within the constraints, we instead assert a general invariant about depositsCount and
        // balance when calling withdrawAll as owner. We'll change approach: make a top-level call
        // to c.withdrawAll() (owner-only), capture whether it reverted, and assert that if it
        // succeeded, C's balance becomes zero and depositsCount is unchanged; if it reverted,
        // neither balance nor depositsCount changed.
    }

    receive() external payable { }
}

contract InvMutTest {
