    constructor(C _c) { c = _c; }

    // single public test entry
    // no Ether needs to be sent to this test; it acts as the owner (deployer of C)
    function run() public payable {
        // observe before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool reverted;
        // top-level state-changing call on c: owner (this contract) calls withdrawAll()
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: withdrawAll either reverts and leaves balance and depositsCount unchanged,
        // or succeeds and sets contract balance to zero while depositsCount is unchanged.
        assert(
            (reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            ||
            (!reverted && afterDeposits == beforeDeposits && afterBalance == 0)
        );
    }

    receive() external payable { }
}
